def table(title,heads,rows,widths):
 x=d.add_paragraph(title,style='Caption'); x.paragraph_format.keep_with_next=True
 t=d.add_table(rows=1, cols=len(heads)); t.autofit=False
 for c,w in zip(t.columns,widths): c.width=Cm(w)
 for c,txt in zip(t.rows[0].cells,heads): c.text=txt
 for row in rows:
  for c,txt in zip(t.add_row().cells,row): c.text=str(txt)
 for ri,r in enumerate(t.rows):
  trPr=r._tr.get_or_add_trPr(); trPr.append(OxmlElement('w:cantSplit'))
  if ri==0: trPr.append(OxmlElement('w:tblHeader'))
  for c,w in zip(r.cells,widths):
   c.width=Cm(w); pr=c._tc.get_or_add_tcPr(); borders=OxmlElement('w:tcBorders')
   for edge in ['top','left','bottom','right']:
    el=OxmlElement('w:'+edge); el.set(qn('w:val'),'single'); el.set(qn('w:sz'),'4'); el.set(qn('w:color'),'D9D9D9'); borders.append(el)
   pr.append(borders)
   if ri==0:
    el=OxmlElement('w:shd'); el.set(qn('w:fill'),'E7E6E6'); pr.append(el)
   for x in c.paragraphs:
    x.paragraph_format.first_line_indent=Cm(0); x.paragraph_format.line_spacing=1.05; x.paragraph_format.space_after=Pt(5); x.paragraph_format.space_before=Pt(5)
    for run in x.runs: run.font.size=Pt(11); run.bold=ri==0
 return t
h('Звіт з дослідницької практики',0)
p('Дослідження методів кластеризації природномовних текстів')
h('Зміст',1)
contents=['Вступ','2 Методика дослідження кластеризації природномовних текстів','2.1 Обґрунтування напряму дослідження','2.2 Постановка задачі та дослідницькі гіпотези','2.3 Методи подання текстів і розв’язання задачі','2.4 Методика організації експерименту','2.5 Програмні засоби та методи вимірювання','2.6 Оцінювання похибок і відтворюваності','4 Результати дослідження та їх аналіз','4.1 Умови та етапи контрольного експерименту','4.2 Результати оцінювання якості та ресурсів','4.3 Перевірка гіпотез та інтерпретація результатів','4.4 Порівняння з дослідженнями інших авторів','4.5 Власний внесок та повнота розв’язання задач','4.6 Достовірність і напрями подальших досліджень','Висновки','Список використаних джерел']
for t in contents:
 x=d.add_paragraph(t); x.paragraph_format.first_line_indent=Cm(0); x.paragraph_format.line_spacing=1.05; x.paragraph_format.space_after=Pt(6)
page(); h('Вступ',1)
p('Автоматичне групування природномовних документів застосовують для впорядкування текстових колекцій, тематичного пошуку та попереднього аналізу інформації. Складність цього завдання зумовлена неоднозначністю слів, різними способами вираження однієї теми та високою розмірністю текстових подань. В українських текстах додатковим чинником є словозміна, через яку споріднені словоформи можуть утворювати окремі ознаки. Тому оцінювання кластеризації має охоплювати послідовність попередньої обробки, векторизації та групування документів.')
p('Об’єкт дослідження — процес автоматичної кластеризації природномовних текстів. Предмет дослідження — залежність якості групування й обчислювальних витрат від способу подання тексту, алгоритму кластеризації та організації повторних ініціалізацій K-Means. Мета дослідницької практики — обґрунтувати методику порівняння цих підходів і встановити можливості та обмеження розробленого програмного інструмента за результатами контрольного експерименту.')
p('Для досягнення мети визначено такі завдання: обґрунтувати вибір методів і критеріїв оцінювання; сформулювати перевірювані гіпотези; описати умови відтворюваного експерименту; проаналізувати якість кластерів, час і відстежувану пам’ять; зіставити результати з відповідними науковими підходами; визначити власний внесок та необхідні подальші дослідження.')
p('Дослідження поєднує теоретичний аналіз методів, аналіз реалізації програми та обчислювальний експеримент. Його емпіричну основу становить контрольний запуск від 20 вересня 2026 року на 50 україномовних документах [1–3]. Еталонні тематичні мітки використовуються лише для оцінювання отриманих груп. Окремо розглядаються технічна працездатність конвеєра та змістовна якість результатів.')
p('Практичне значення роботи полягає у створенні спільного середовища для порівняння методів і збереження умов досліду. Контрольний експеримент показав низьку відокремленість кластерів у просторі TF-IDF та відсутність виграшу за часом для паралельного багатостартового варіанта на малому корпусі. Ці спостереження визначають межі висновків і програму подальших випробувань.')
page(); h('2 Методика дослідження кластеризації природномовних текстів',1)
h('2.1 Обґрунтування напряму дослідження')
p('Напрям дослідження обрано з огляду на необхідність порівнювати алгоритми за однакових умов. Оцінка лише кластеризатора не пояснює результату, якщо одночасно змінюються очищення текстів, словник ознак або модель подання. Тому одиницею порівняння є повний обчислювальний варіант, для якого зафіксовано корпус, попередню обробку, векторизатор, алгоритм та його параметри.')
p('У розвитку текстових подань простежується перехід від частотних ознак до векторів слів, підслівних одиниць і речень. TF-IDF відображає лексичний склад документа; FastText враховує символьні n-грами [6]; Sentence-BERT створює подання речень для семантичного порівняння [7]. Ці підходи використовують різні джерела інформації, тому їхню придатність слід перевіряти на відповідному корпусі. Сам факт застосування нейронної моделі не є доказом вищої якості групування.')
p('Для початкового експерименту обрано TF-IDF, оскільки цей метод не потребує попереднього завантаження мовної моделі та дає змогу дослідити вплив кластеризатора у спільному просторі ознак. K-Means, агломеративний метод і DBSCAN представляють відповідно центроїдний, ієрархічний і щільнісний підходи. Parallel K-Means введено для перевірки організації багатостартового пошуку. Такий склад методів охоплює різні принципи утворення груп, а не лише варіанти одного алгоритму.')
h('2.2 Постановка задачі та дослідницькі гіпотези')
p('Нехай D — корпус із N документів. Після попередньої обробки та векторизації кожному документу відповідає вектор із p ознак, а весь корпус подано матрицею X розміру N × p. Алгоритм формує вектор міток кластерів; для щільнісних методів допускається мітка шуму −1. Потрібно встановити, які конфігурації утворюють змістовні групи за прийнятного часу та використання пам’яті. Порівняння є багатокритеріальним: найменший час сам по собі не визначає найкращого розв’язку.')
p('Гіпотеза H1: вибір найкращого результату серед кількох ініціалізацій K-Means може поліпшити геометричні характеристики розбиття порівняно з одним стартом. Перевірка має розрізняти цільову функцію inertia, внутрішні метрики та відповідність тематичним міткам. Зменшення inertia не означає автоматичного зростання F1 або ARI.')
p('Гіпотеза H2: конкурентне виконання однакової кількості незалежних стартів скорочує час порівняно з їх послідовним виконанням за достатнього обсягу даних. Належний контроль передбачає однакові зерна випадковості, кількість стартів і обмеження внутрішніх потоків бібліотек. Порівняння восьми стартів з одним стартом не ізолює ефект паралелізму.')
p('Гіпотеза H3: найбільший Silhouette може відповідати кількості кластерів, відмінній від кількості тематичних класів. Для її перевірки зіставляються рекомендація K за геометричним критерієм та відома структура корпусу. Гіпотеза H4: лематизація та семантичні подання можуть поліпшити групування українських текстів. Для H4 потрібні окремі зіставні запуски; контрольний експеримент із TF-IDF без лематизації її не перевіряє.')
h('2.3 Методи подання текстів і розв’язання задачі')
p('Попередня обробка виконується модулями очищення, токенізації, вилучення стоп-слів та, за вибором користувача, лематизації. Нормалізація зменшує варіативність форми запису, однак може видаляти корисні мовні ознаки. Тому список стоп-слів і режим лематизації належать до контрольованих умов. Для контекстних моделей доцільно окремо порівнювати початкові речення та тексти, відновлені з очищених токенів.')
p('У реалізації TF-IDF використано TfidfVectorizer із граничною кількістю 5000 ознак. За стандартного згладжування вага терміна визначається як добуток його частоти в документі та величини ln((1 + N)/(1 + df)) + 1, де df — кількість документів із цим терміном. Далі вектор нормується за евклідовою нормою [4]. Код перетворює розріджену матрицю на щільну, що спрощує передачу даних між компонентами, але збільшує потребу в пам’яті на великих корпусах [2].')
table('Таблиця 2.1 — Порівняльні характеристики методів подання',['Метод','Принцип','Обмеження у дослідженні'],[
['TF-IDF','Ваги слів у документах','Не моделює синонімію; чутливий до словоформ'],['Word2Vec','Агрегація векторів слів','Навчання на малому корпусі обмежує надійність подань'],['FastText','Вектори з урахуванням частин слова','Потребує достатніх навчальних даних'],['Doc2Vec','Навчання векторів документів','Чутливість до обсягу даних і параметрів'],['Sentence-BERT','Кодування речень попередньо навченою моделлю','Потрібна модель; вплив очищення перевіряється окремо']],[3,6,8])
p('K-Means мінімізує суму квадратів евклідових відстаней документів до центрів відповідних кластерів. На кожній ітерації об’єкти призначають найближчим центрам, після чого центри перераховують. Орієнтовні витрати одного запуску становлять O(NKpI), де I — кількість ітерацій. Число K задається наперед, а результат залежить від початкових центрів. У контрольній конфігурації застосовано k-means++ та random_state = 42 [2; 5].')
p('Parallel K-Means створює R незалежних моделей із n_init = 1 та зернами 42, 43, …, 42 + R − 1. ThreadPoolExecutor виконує не більше min(W, R) моделей одночасно. Після завершення обираються мітки кандидата з мінімальною inertia. Для того самого набору кандидатів мінімум не перевищує значення жодного окремого кандидата; це властивість процедури відбору. Проте ні прискорення, ні поліпшення тематичного групування з неї не випливають. Значення inertia наразі не входить до експортованої таблиці, що обмежує її ретроспективний аналіз.')
p('Агломеративний метод починає з окремих об’єктів і послідовно об’єднує групи. Критерій Ward обирає об’єднання з найменшим приростом внутрішньокластерної суми квадратів. Він дає ієрархію розбиттів, але потребує уваги до витрат пам’яті зі зростанням N. DBSCAN формує групи через околи заданого радіуса eps та поріг min_samples. Його перевагою є явне виділення шуму; обмеженням — чутливість до масштабу й розподілу відстаней у просторі ознак.')
h('2.4 Методика організації експерименту')
p('Експеримент організовано як послідовність завантаження корпусу, мовної обробки, формування матриці ознак, запуску кластеризаторів, оцінювання та збереження результатів. Для кожного векторизатора алгоритми отримують спільну матрицю X. Під час порівняння кластеризаторів незмінними залишаються склад корпусу, попередня обробка та подання текстів. Незалежною змінною є алгоритм разом із явно заданою конфігурацією; залежними — показники якості, кількість груп, частка шуму та витрати ресурсів.')
p('У програмі рекомендацію K формують перебором значень від 2 до min(10, N − 1) за найбільшим Silhouette для K-Means. Ця рекомендація не замінює введений параметр автоматично. Для дослідження H3 потрібно зіставити рекомендоване K з числом тем і додатково перевірити зовнішню якість розбиття за цим K. Оптимізацію за еталонною розміткою та підсумкове оцінювання доцільно розділяти між різними корпусами або незалежними вибірками.')
p('Базовий дослід характеризує поведінку програми в конкретних умовах. Для узагальнення потрібна серія на корпусах різного обсягу, довжини документів і тематичної близькості. Під час розширення експерименту слід змінювати один чинник або використовувати наперед визначений факторний план. Невдалі розбиття, помилки залежностей та віднесення всіх документів до шуму мають залишатися в протоколі як результати спостережень.')
h('2.5 Програмні засоби та методи вимірювання')
p('Інструмент реалізовано мовою Python. Сервіс ExperimentService керує конвеєром; scikit-learn забезпечує базові алгоритми й метрики; NumPy та pandas — роботу з матрицями й таблицями; Gensim і sentence-transformers — додаткові подання; tkinter — графічний інтерфейс. Результати зберігаються у CSV, JSON та HTML, конфігурація — у JSON, а manifest.json пов’язує артефакти запуску. Така організація дає змогу повторно переглядати дослід без нового навчання [2].')
p('Внутрішні критерії описують геометрію кластерів. Для об’єкта коефіцієнт силуету дорівнює різниці між середньою відстанню до найближчої іншої групи та середньою відстанню всередині своєї групи, поділеній на більшу з цих відстаней. Значення біля нуля вказують на слабку відокремленість. Davies–Bouldin оцінює співвідношення внутрішнього розсіювання та відстаней між центрами; менші значення бажані. Calinski–Harabasz зіставляє міжкластерне й внутрішньокластерне розсіювання; більші значення бажані за порівнюваних умов.')
p('Зовнішні критерії зіставляють кластери з тематичними мітками. F1 macro усереднює F1 класів, а F1 micro агрегує внески об’єктів. Для F1 код спочатку виконує взаємно однозначне зіставлення кластерів і класів за максимумом збігів. ARI оцінює узгодженість пар з поправкою на випадковість; NMI та V-measure використовують інформаційні характеристики розбиттів. Їх обчислюють за початковими номерами кластерів. Мітки шуму вилучаються перед зовнішнім оцінюванням, тому разом із цими метриками потрібно подавати частку охоплених документів.')
p('Час визначається таймером perf_counter окремо для векторизації та кластеризації. Пам’ять вимірюється через tracemalloc і подається як середній пік відстежуваних виділень у КіБ, тобто байтах, поділених на 1024. Це не повний обсяг оперативної пам’яті процесу. Монітор CPU використовує інтервал 0,1 с; показник процесу нормується на кількість логічних ядер, а показники по ядрах відображають системну активність. Вимірювач повертає останній результат обчислення та агреговані витрати всіх повторів.')
h('2.6 Оцінювання похибок і відтворюваності')
p('Випадкові коливання часу спричиняють планувальник операційної системи, фонові процеси та стан кешів. Систематичні відмінності можуть виникати через прогрів бібліотек, профілювання, різну кількість внутрішніх потоків і нерівний обсяг виконаної роботи. Для коротких операцій частота опитування CPU недостатня для детальної характеристики навантаження. Тому показники CPU не використовуються як головний доказ переваги алгоритму.')
p('Для m незалежних часових вимірювань слід зберігати кожне значення, середнє, вибіркове стандартне відхилення та стандартну похибку середнього. В останній стандартне відхилення ділять на квадратний корінь із m. У програмі обчислюється time_std із нормуванням на m, але сервіс не переносить його до підсумкового експорту. Наявні середні трьох повторів не дозволяють відновити розкид або обґрунтовано побудувати довірчі інтервали.')
p('Повторення з однаковим random_state не є незалежними випробуваннями стійкості якості. Для цього потрібні різні зерна, зіставні набори початкових умов і розподіли метрик. Відтворюваність також потребує фіксації версій бібліотек, характеристик обладнання, хешу корпусу та моделі, порядку документів і режиму багатопотоковості. Поточна конфігурація зберігає основні параметри, але не весь цей набір відомостей.')
page(); h('4 Результати дослідження та їх аналіз',1)
h('4.1 Умови та етапи контрольного експерименту')
p('Контрольний експеримент проведено 20 вересня 2026 року в середовищі macOS-27.0-x86_64-i386-64bit, Python 3.12.13 [1; 3]. Корпус demo_texts.csv містить 50 україномовних документів і п’ять збалансованих класів: технології, спорт, економіка, наука та культура, по 10 документів у кожному. Це демонстраційний набір, який придатний для перевірки конвеєра, але не репрезентує всі типи українських текстів. Точні модель процесора та обсяг RAM у протоколі не зафіксовано; вимоги технічного завдання не можна підставляти замість виміряних характеристик середовища.')
p('На підготовчому етапі перевірено імпорт еквівалентних TXT, CSV та JSON. Початкова спроба з лематизацією завершилася помилкою через відсутність українського словника pymorphy3. Подальший контрольний запуск виконано з вимкненою лематизацією. Отже, результати характеризують саме цей режим; працездатність української лематизації в зазначеному середовищі не підтверджено.')
table('Таблиця 4.1 — Умови контрольного запуску',['Параметр','Значення'],[['Векторизація','TF-IDF, до 5000 ознак'],['Обробка','Стоп-слова ввімкнено, лематизацію вимкнено'],['K та ініціалізація','K = 5; k-means++'],['Агломеративний метод','linkage = ward'],['DBSCAN','eps = 0,5; min_samples = 5'],['Parallel K-Means','8 стартів, 4 робочі потоки; зерна 42–49'],['Повтори','3 вимірювання кожної операції'],['Рекомендація K','Перебір від 2 до 10 за Silhouette']],[6,11])
p('Після підготовки виконано чотири комбінації TF-IDF з алгоритмами K-Means, Parallel K-Means, hierarchical та DBSCAN. Конвеєр сформував метрики, графіки й конфігурацію. Контрольний сценарій підтвердив чотири записи без поля error, збереження результатів та їх повторне завантаження. Перевірки відсутнього файлу й відсутньої текстової колонки завершилися очікуваними винятками. Звіт практики також фіксує успішне виконання двох модульних тестів попередньої обробки. Ці перевірки підтверджують базовий сценарій, але не замінюють експериментального оцінювання якості.')
h('4.2 Результати оцінювання якості та ресурсів')
rows=json.loads(Path('reports/experiments/experiment_20260920_152430/results_20260920_152430.json').read_text())
names=['K-Means','Parallel K-Means','Агломеративний','DBSCAN']
def num(x,n=4): return f'{x:.{n}f}'.replace('.',',')
table('Таблиця 4.2 — Внутрішні показники якості',['Алгоритм','Групи / шум','Silhouette','Davies–Bouldin','Calinski–Harabasz'],[[name,f"{r['clusters_found']} / {r['noise_documents']}",*[num(r[k]) if r['clusters_found'] else '—' for k in ['silhouette','davies_bouldin','calinski_harabasz']]] for name,r in zip(names,rows)],[4,3,3,3.5,3.5])
p('Найбільший Silhouette отримано для агломеративного методу — 0,0106, а найменший Davies–Bouldin для Parallel K-Means — 2,1687. Уже ця відмінність показує, що внутрішні критерії не задають єдиного порядку переваги. Усі коректно обчислені значення Silhouette близькі до нуля; тому навіть найкращий показник цього запуску не свідчить про добре відокремлені тематичні групи.')
table('Таблиця 4.3 — Узгодженість із тематичними класами',['Алгоритм','F1 macro','F1 micro','ARI','NMI / V'],[[name,*[num(r[k]) if r['clusters_found'] else '—' for k in ['f1_macro','f1_micro','ari','nmi']]] for name,r in zip(names,rows)],[4,3.25,3.25,3.25,3.25])
p('Для трьох розбиттів без шуму NMI та V-measure у збережених результатах збігаються. Агломеративний метод має найбільші F1 macro (0,3029), F1 micro (0,3400) і NMI (0,1982). Водночас найбільший ARI серед перевірених розбиттів має K-Means (0,0169). Значення ARI близькі до нуля, а для Parallel K-Means воно від’ємне (−0,0027). Це вказує на слабку узгодженість отриманих груп із заданими темами з погляду цього критерію.')
p('DBSCAN не утворив жодного кластера й позначив шумом усі 50 документів. Тому в таблицях використано прочерк для змістовно неоцінюваних метрик. У JSON внутрішні показники мають службове значення −1, а зовнішні — 0 через порожню множину після вилучення шуму. Їх не можна трактувати як звичайні оцінки розбиття або включати до ранжування якості.')
table('Таблиця 4.4 — Середні витрати кластеризації',['Алгоритм','Час, с','Пік пам’яті, КіБ'],[[name,num(r['clustering_seconds'],6),num(r['clustering_memory_kb'],2)] for name,r in zip(names,rows)],[7,5,5])
p('Середній час векторизації становив 0,010754 с, а середній пік відстежуваної пам’яті — 219,74 КіБ. Ці значення спільні для чотирьох алгоритмів, оскільки матрицю ознак сформовано до їх запуску. Час кластеризації не включає імпорт корпусу, попередню обробку, пошук рекомендованого K та побудову графіків; його не слід ототожнювати з тривалістю всього досліду.')
p('Parallel K-Means витратив приблизно у 8,60 раза більше часу та у 3,24 раза більше відстежуваної пікової пам’яті, ніж базовий K-Means. Це співвідношення обчислено з агрегованих значень таблиці 4.4. Воно характеризує фактичні конфігурації різного обсягу роботи і не є оцінкою прискорення восьми однакових стартів. DBSCAN завершився найшвидше, але не сформував груп, тому його час не доводить практичної переваги за завданням тематичного групування.')
h('4.3 Перевірка гіпотез та інтерпретація результатів')
p('Щодо H1, у Parallel K-Means порівняно з K-Means зросли Silhouette та Calinski–Harabasz, а Davies–Bouldin зменшився. Це узгоджується з припущенням про можливе поліпшення внутрішньої структури. Водночас F1 macro знизився з 0,2390 до 0,2364, F1 micro — з 0,3200 до 0,2800, а ARI — з 0,0169 до −0,0027. Отже, поліпшення геометричних показників не супроводжувалося загальним поліпшенням відтворення тем. Без збережених inertia та серії незалежних ініціалізацій H1 має лише часткову емпіричну підтримку.')
p('Гіпотеза H2 у наявному досліді не перевірена належним контрольним порівнянням: відсутній послідовний варіант із тими самими вісьмома стартами. Практичного скорочення часу відносно базового K-Means на цьому корпусі не спостерігається. Можливими причинами є додаткова робота та витрати організації потоків, однак їх окремий внесок не вимірювався. Цей результат не дає підстав ані оголосити загальне прискорення, ані відкинути його можливість для більших корпусів.')
p('Для H3 отримано конкретне спостереження: рекомендоване K дорівнює 7 за наявності п’яти еталонних тем. Отже, геометрична рекомендація не відтворює автоматично тематичну структуру. Збережені метрики основних алгоритмів обчислено за K = 5; вони не описують розбиття на сім кластерів. Щоб порівняти тематичну якість K = 5 і K = 7, необхідний окремий запуск із відповідними зовнішніми метриками.')
p('Гіпотеза H4 залишається відкритою, оскільки немає зіставного контрольного результату з лематизацією та нейронними поданнями. Відмова DBSCAN за eps = 0,5 свідчить лише про невідповідність цієї конфігурації сформованому простору ознак. Для ненульових L2-нормованих векторів квадрат евклідової відстані дорівнює 2 − 2cos, тому радіус 0,5 вимагає косинусної подібності щонайменше 0,875. Це пояснює суворість порога, але фактичний розподіл відстаней потребує окремого аналізу.')
h('4.4 Порівняння з дослідженнями інших авторів')
p('У праці українських дослідників Д. В. Ланде та О. О. Рибака розглянуто семантичне індексування документів із кібербезпеки через виділення концептів і побудову мереж їхніх зв’язків [8]. Спільним є завдання виявлення тематично споріднених документів. Відмінність полягає у поданні: мережі концептів враховують семантичні зв’язки, тоді як контрольний TF-IDF описує лексичні збіги. Отримана слабка тематична узгодженість мотивує перевірку змістовніших подань, але не доводить переваги мережевого підходу без його запуску на тому самому корпусі.')
p('Бояновський та співавтори показали застосовність підслівних векторів до задач подібності слів і аналогій у дев’яти мовах [6]. Цей результат обґрунтовує інтерес до FastText для мов із розвиненою морфологією. Проте в нашому контрольному досліді оцінюється кластеризація документів, а не подібність окремих слів. Тому результати цих задач не можна порівнювати як однакові показники точності; необхідна власна перевірка FastText на українських документах.')
p('Раймерс і Гуревич запропонували Sentence-BERT для отримання семантично змістовних подань речень і їх ефективного порівняння [7]. Це визначає альтернативу частотному поданню, коли одна тема виражається різною лексикою. У програмі передбачено багатомовну модель paraphrase-multilingual-MiniLM-L12-v2, однак наявність адаптера не означає, що її якість уже підтверджено контрольним запуском. Оцінки з оригінальної праці не переносяться безпосередньо на цю модель та демонстраційний корпус.')
p('Таким чином, зіставлення з публікаціями є методологічним: визначено спільне завдання, відмінності подань і межі порівнюваності. Кількісне твердження про перевагу над результатами інших авторів було б необґрунтованим через відмінність даних, мов, моделей і критеріїв. Для такого порівняння потрібно відтворити відповідні базові методи в одному експериментальному протоколі.')
h('4.5 Власний внесок та повнота розв’язання задач')
p('Власний внесок полягає в інтеграції обробки українських текстів, різних подань і кластеризаторів у керований дослідницький конвеєр, реалізації паралельних незалежних перезапусків та збереженні умов і результатів дослідів. Дослідницьким результатом є встановлення розбіжності між внутрішніми й зовнішніми оцінками на контрольному корпусі, виявлення непридатності вибраних параметрів DBSCAN та відсутності виграшу за часом відносно базової конфігурації K-Means.')
p('Новизна в межах виконаної роботи має прикладний та експериментальний характер. Вона стосується конкретної організації інструмента й отриманих спостережень, а не створення нового математичного класу алгоритмів. Незалежні перезапуски K-Means і вибір мінімальної inertia є відомими принципами. Для заяви про загальнонаукову алгоритмічну новизну потрібні окремий аналіз попередніх праць і доказ відмінності запропонованого методу.')
p('Завдання формування методики, реалізації спільного сценарію, обчислення метрик і збереження артефактів виконано для перевіреної конфігурації. Порівняння чотирьох алгоритмів із TF-IDF проведено; загальне ранжування всіх підтримуваних векторизаторів не встановлено. Працездатність лематизації, масштабованість, стабільність якості та повна відповідність технічному завданню потребують додаткового підтвердження. Така оцінка повноти відділяє реалізовану можливість від експериментально перевіреної властивості.')
h('4.6 Достовірність і напрями подальших досліджень')
p('Достовірність наведених чисел забезпечується їх зв’язком зі збереженими JSON-результатами та конфігурацією одного запуску [3]. Таблиці відтворюють ці значення з округленням. Водночас малий демонстраційний корпус, одна конфігурація та відсутність індивідуальних часових спостережень обмежують можливість узагальнення. Результати не встановлюють статистично значущої переваги жодного алгоритму для українських текстів загалом.')
p('Є також обмеження оцінювання: зовнішні метрики вилучають шум, тоді як внутрішні за наявності кількох груп можуть враховувати мітку −1 як окрему групу. Перед розширенням досліду необхідно узгодити цю політику та позначати неоцінювані випадки пропущеними значеннями. Дендрограма в програмі завжди використовує Ward; для дослідів з іншим linkage її потрібно узгодити з кластеризатором. Двовимірні проєкції мають ілюстративну роль і не замінюють метрики у вихідному просторі.')
p('Наступний етап має включати встановлення українського словника та контрольне порівняння режимів лематизації; перевірку TF-IDF, FastText, Word2Vec, Doc2Vec і Sentence-BERT на тих самих розмічених корпусах; добір параметрів щільності з урахуванням відстаней; повторення дослідів на різних тематичних вибірках. Для нейронних моделей потрібно фіксувати джерело навчальних даних і відділяти ефект попереднього навчання від ефекту алгоритму кластеризації.')
p('Для перевірки паралелізму слід зіставити послідовні та паралельні вісім стартів із зернами 42–49, однаковим числом внутрішніх потоків та кількома обсягами корпусу. Потрібно зберігати inertia, мітки кожного документа, сирі часові вимірювання, прогріті й початкові запуски окремо, а також незалежні серії зерен. Лише після цього можна оцінити прискорення, його невизначеність і ціну у пам’яті. Такі досліди перевірятимуть гіпотезу незалежно від того, чи буде результат позитивним.')
page(); h('Висновки',1)
p('У межах дослідницької практики обґрунтовано методику порівняння кластеризації природномовних текстів, яка охоплює подання документів, алгоритм групування, внутрішню структуру кластерів, узгодженість із тематичними мітками та витрати ресурсів. Сформульовано гіпотези щодо багатостартового пошуку, паралельного виконання, вибору числа кластерів і мовної нормалізації. Для кожної визначено умови перевірки та межі висновків.')
p('Контрольний експеримент на 50 українських документах підтвердив працездатність базового конвеєра TF-IDF з чотирма алгоритмами. Найбільші Silhouette (0,0106) і F1 macro (0,3029) отримано для агломеративного методу, проте низькі абсолютні значення Silhouette та близькі до нуля ARI свідчать про слабку структуру й тематичну узгодженість розбиттів. DBSCAN за eps = 0,5 та min_samples = 5 не сформував груп, віднісши весь корпус до шуму.')
p('Parallel K-Means поліпшив частину внутрішніх критеріїв відносно базового K-Means, але не забезпечив поліпшення F1 і ARI. Його середній час був приблизно у 8,60 раза більшим. Оскільки порівнювалися конфігурації різного обсягу роботи, цей результат не перевіряє прискорення однакової кількості стартів. Рекомендація K = 7 за наявності п’яти тем додатково показала, що геометричний оптимум не тотожний тематичному.')
p('Розроблений інструмент має практичну цінність як середовище керування порівняльними дослідами. Власний внесок охоплює його інтеграцію, паралельну організацію перезапусків і аналіз збереженого експерименту. Зіставлення з українськими та зарубіжними працями обґрунтовує подальшу перевірку семантичних подань, але не дає підстав заявляти про перевищення опублікованих результатів.')
p('Мету практики досягнуто в частині обґрунтування методики та встановлення можливостей і обмежень контрольного сценарію. Для завершеного порівняльного дослідження необхідні більші незалежні корпуси, перевірена лематизація, серії різних ініціалізацій і повні протоколи вимірювань. Підсумковий вибір методу має спиратися на спільний аналіз якості, охоплення документів і ресурсів, із збереженням результатів, які не підтверджують початкові гіпотези.')
